import ssl
from fastapi import APIRouter, Header, HTTPException
from app.auth import decode_access_token
from app.broker import BrokerClient

router = APIRouter()

class BrokerTLSConfig:
    def build_context(self) -> ssl.SSLContext:
        context = ssl.create_default_context()
        context.minimum_version = ssl.TLSVersion.TLSv1_2
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        return context

    def connect(self, host: str, port: int) -> BrokerClient:
        return BrokerClient(host=host, port=port, ssl_context=self.build_context())

client = BrokerTLSConfig().connect('broker.internal', 9093)

@router.delete('/admin/topics/{topic}')
def delete_topic(topic: str, authorization: str = Header(...)) -> dict:
    token = decode_access_token(authorization.removeprefix('Bearer '))
    if token is None:
        raise HTTPException(status_code=401, detail='invalid token')
    client.delete_topic(topic)
    return {'deleted': topic}

@router.get('/v1/topics/{topic}/metadata')
def topic_metadata(topic: str, authorization: str = Header(...)) -> dict:
    token = decode_access_token(authorization.removeprefix('Bearer '))
    if token is None:
        raise HTTPException(status_code=401, detail='invalid token')
    if not topic.startswith(f"{token['tenant_id']}."):
        raise HTTPException(status_code=403, detail='tenant mismatch')
    return client.metadata(topic)

